	public class UseLightningShuriken : ProjectileAttackState
	{
		public new static string staticID = "UseLightningShuriken";

		public UseLightningShuriken(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			allowSelfTransition = true;
			allowRepeating = true;
			SetAnimTimes(0.2f, 0.2f, 0.3f, 0.45f, 0.6f);
			InitChargeSkillSettings(3, 0f, skillData, this);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			SetSkillLevel((!IsEmpowered) ? 1 : 2);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			Vector2 vector = parent.attackOriginTrans.position;
			FireProjectile(CreateProjectile(Shuriken.LightningPrefab, vector), inputVector, setKnockbackVector: true, 0f, 0f, string.Empty);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(3, vector);
			SoundManager.PlayAudioWithDistance("TeleStrike", vector, null, 24f, -1f, 1.25f);
		}
	}

	public class UseLightningSword : SkillState
	{
		public new static string staticID = "UseLightningSword";

		private LightningSword currentLS;

		public UseLightningSword(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isMeleeSkill = true;
			allowSelfTransition = true;
			SetAnimTimes(0.15f, 0.2f, 0.25f, 0.55f, 0.75f);
			InitChargeSkillSettings(2, 0f, skillData, this);
		}

		public override void OnEnter()
		{
			allowSelfTransition = !isUltimate;
			base.OnEnter();
			if (isUltimate)
			{
				StartCooldownTimer(99f);
			}
			if (!(parent.GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false) == Vector2.zero) && (!parent.inputDevice.IsMouseAim || !(parent.inputDevice.GetSqMouseDist < 5f)))
			{
				parent.movement.moveVector = inputVector;
				parent.movement.MoveToMoveVector(20f);
			}
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			parent.movement.EndMovement();
			currentLS = ChaosInst<LightningSword>(LightningSword.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(inputVector));
			currentLS.attack.SetAttackInfo(parent.skillCategory, skillID, (!isUltimate) ? 1 : 3, isUltimate);
			currentLS.attack.knockbackOverwriteVector = inputVector;
			currentLS.SetVars(inputVector, (!IsEmpowered) ? 4 : 5, isUltimate);
			if (isUltimate)
			{
				SoundManager.PlayWithDistAndSPR("StandardHeavySwing", parent.attackOriginTrans.position);
			}
			else
			{
				string audioID = "WindSlashBasic";
				Vector2? soundOrigin = parent.attackOriginTrans.position;
				float overridePitch = SoundManager.StandardPitchRange * 0.9f;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.15f, overridePitch);
			}
			CameraController.ShakeCamera(0.25f);
		}
	}

	public class UseLightningXStrike : ProjectileAttackState
	{
		public new static string staticID = "UseLightningXStrike";

		private LightningXStrike currentLX;

		private LightningXStrike leftStrike;

		private LightningXStrike rightStrike;

		private Vector2 currentPosition;

		private Vector2 targetVector;

		private Vector2 perpendVec;

		private Vector2 leftVec;

		private Vector2 rightVec;

		private float calcTime;

		private int burstLevel = 2;

		private float burstScale = 1.25f;

		public override string OnEnterAnimStr => parent.PBAoEAnimStr;

		public UseLightningXStrike(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.2f, 0.2f, 0.3f, 0.55f, 0.75f);
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			currentPosition = parent.attackOriginTrans.position;
			targetVector = inputVector;
			if (isUltimate)
			{
				burstLevel = 3;
				burstScale = 2.5f;
				CreateX(1.75f, 30f, inputVector * 0.25f, useBurst: true);
				CreateX(2.5f, 27f, Vector2.zero);
				CreateX(3f, 24f, inputVector * -0.25f);
				CreateX(3.5f, 22.5f, inputVector * -0.5f);
				return;
			}
			burstLevel = 2;
			burstScale = 1.25f;
			if (IsEmpowered)
			{
				CreateX(1.75f, 16f, inputVector * 0.25f, useBurst: true);
				CreateX(2.25f, 17f, inputVector * -0.75f);
			}
			else
			{
				CreateX(1.75f, 16f, inputVector * 0.25f);
