using System.Collections.Generic;

public class SevenFlushLightning : SevenFlush
{
	public static string staticID = "SevenFlushLightning";

	private Dictionary<string, NumVarStatMod> fieldModDict;

	protected override string ExtraInfo => PercentToStr(0.2f, "+");

	public SevenFlushLightning()
		: base(staticID, ElementType.Lightning)
	{
		category = Category.Offense;
		fieldModDict = new Dictionary<string, NumVarStatMod>
		{
			{
				StatData.critChStr,
				new NumVarStatMod(staticID, 0.2f, modPriority)
			},
			{
				StatData.shockChStr,
				new NumVarStatMod(staticID, 1f, modPriority, VarStatModType.Override)
			},
			{
				StatData.shockLvStr,
				new NumVarStatMod(staticID, 2f, modPriority)
			}
		};
	}

	public override void ApplyMods(bool givenStatus)
	{
		StatManager.ModifyAllStatData(fieldModDict, parentSkillCategory, ApplyConditional, givenStatus);
	}

	private bool ApplyConditional(StatData givenSD)
	{
		return ElementAndStatusConditional(givenSD) && givenSD.GetValue<int>(StatData.damageStr) > 0;
	}
}
