using UnityEngine;

public class Torch : Destructible
{
	public enum TorchColor
	{
		Orange,
		Green,
		Purple,
		Red,
		Blue
	}

	public bool lightOnStart = true;

	public bool useTrigger;

	public bool lit = true;

	public bool autoAdjustBrightness = true;

	private Light stageLight;

	private Light torchLight;

	public TorchColor torchColor;

	private Material spriteMaterial;

	private Color darkColor;

	private Color lightColor;

	private static int paletteCount = -1;

	private ParticleSystem dustEmitter;

	private SpriteRenderer outterHalo;

	private SpriteRenderer innerHalo;

	public override void Start()
	{
		base.Start();
		GameObject gameObject = GameObject.Find("StageLight");
		if (gameObject != null)
		{
			stageLight = gameObject.GetComponentInChildren<Light>();
		}
		torchLight = GetComponentInChildren<Light>();
		if (stageLight != null && autoAdjustBrightness)
		{
			float num = Mathf.Lerp(1f, 0.18f, stageLight.intensity / 0.7f);
			torchLight.intensity *= num;
		}
		outterHalo = transform.Find("OutterHalo").GetComponent<SpriteRenderer>();
		innerHalo = outterHalo.transform.Find("InnerHalo").GetComponent<SpriteRenderer>();
		SetColor();
		Toggle(lightOnStart);
	}

	public void SetColor()
	{
		Transform transform = base.transform.Find("TorchSprite") ?? base.transform.Find("WallTorchSprite");
		spriteMaterial = transform.GetComponentInChildren<SpriteRenderer>().material;
		if (paletteCount == -1)
		{
			paletteCount = (int)spriteMaterial.GetFloat("_PaletteCount");
		}
		spriteMaterial.SetFloat("_PaletteIndex", (uint)torchColor);
		darkColor = ((Texture2D)spriteMaterial.GetTexture("_Palette")).GetPixel(Mathf.CeilToInt((float)spriteMaterial.GetTexture("_Palette").width * 0.326f), Mathf.CeilToInt((float)spriteMaterial.GetTexture("_Palette").height * (float)torchColor / (float)paletteCount));
		lightColor = ((Texture2D)spriteMaterial.GetTexture("_Palette")).GetPixel(Mathf.CeilToInt((float)spriteMaterial.GetTexture("_Palette").width * 0.4565f), Mathf.CeilToInt((float)spriteMaterial.GetTexture("_Palette").height * (float)torchColor / (float)paletteCount));
		torchLight.color = darkColor;
		dustEmitter = GetComponentInChildren<ParticleSystem>();
		dustEmitter.startColor = darkColor;
		if (torchColor == TorchColor.Purple)
		{
			innerHalo.color = new Color32((byte)(darkColor.r * 255f), (byte)(darkColor.g * 255f), (byte)(darkColor.b * 255f), 40);
			innerHalo.color = new Color32((byte)(lightColor.r * 255f), (byte)(lightColor.g * 255f), (byte)(lightColor.b * 255f), 40);
		}
	}

	public void Toggle(bool light = true)
	{
		if (destroyed)
		{
			light = false;
		}
		if (light)
		{
			anim.Play("Lit", -1, Random.value);
			lit = true;
		}
		else
		{
			anim.Play("Unlit");
			lit = false;
		}
	}

	public override void Break()
	{
		base.Break();
		Toggle(light: false);
		if (lit)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SmokeSmallEmitter").Emit(3, transform.position + Vector3.up * 2f);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeSmallEmitter").Emit(2, transform.position + Vector3.up * 2.5f);
			PoolManager.GetPoolItem<ParticleEffect>("SmokeEmitter").Emit(12, transform.position + Vector3.up * 1.75f);
		}
	}
