	public void PushSkillData()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			foreach (Player.SkillState value in player.skillsDict.Values)
			{
				if (value != null)
				{
					if (!skillDataDictionary.ContainsKey(value.skillID))
					{
						skillDataDictionary.Add(value.skillID, new StoredSkillData());
					}
					if (!skillDataDictionary[value.skillID].isUnlocked)
					{
						skillDataDictionary[value.skillID].isUnlocked = value.isUnlocked;
					}
					if (!skillDataDictionary[value.skillID].signatureUnlocked)
					{
						skillDataDictionary[value.skillID].signatureUnlocked = value.signatureUnlocked;
					}
				}
			}
		}
	}

	public void PullSkillData()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			foreach (KeyValuePair<string, StoredSkillData> item in skillDataDictionary)
			{
				if (player.skillsDict.ContainsKey(item.Key) && player.skillsDict[item.Key] != null)
				{
					player.skillsDict[item.Key].isUnlocked = item.Value.isUnlocked;
					player.skillsDict[item.Key].signatureUnlocked = item.Value.signatureUnlocked;
				}
			}
		}
	}

