	public void UpdateSkillDataEntry(string skillID, ElementType element, int useCountIncrement = 0, bool overdrive = false)
	{
		if (!(Application.loadedLevelName == "PlayerRoom") && !(Application.loadedLevelName == "Hub") && !Application.loadedLevelName.Contains("PvP") && useCountIncrement > 0)
		{
			if (!skillDataDictionary.ContainsKey(skillID))
			{
				skillDataDictionary.Add(skillID, new StoredSkillData());
			}
			skillDataDictionary[skillID].useCount += useCountIncrement;
			if (overdrive)
			{
				skillDataDictionary[skillID].overdriveCount += useCountIncrement;
			}
			if (!elementUsage.ContainsKey(element))
			{
				elementUsage.Add(element, 0);
			}
			elementUsage[element] += useCountIncrement;
		}
	}

