using System;

[Serializable]
public class RunHistoryEntry
{
	public GameMode gameMode;

	public int loopCount;

	public int tierCount = 1;

	public int stageCount = 1;

	public string timeText = "0:0";

	public string timeStr = "0.0";

	public string[] relicIDs = new string[12];

	public string[] arcanaIDs = new string[7];

	public int[] arcanaTypes = new int[7];

	public string outfitID = "Hope";

	public bool outfitUpgraded;

	public bool loopMode;

	public bool speedMode;

	public bool hardMode;

	public bool extraGold;

	public bool randomMode;

	public bool floorLock;

	public bool superSura;

	public bool coop;

	public static bool IsBetterRun(RunHistoryEntry newEntry, RunHistoryEntry oldEntry = null)
	{
		if (oldEntry == null)
		{
			return true;
		}
		if (newEntry.gameMode == GameMode.Endless)
		{
			int num = newEntry.loopCount * 100 + newEntry.tierCount * 10 + newEntry.stageCount;
			int num2 = oldEntry.loopCount * 100 + oldEntry.tierCount * 10 + oldEntry.stageCount;
			if (num > num2)
			{
				return true;
			}
			if (num < num2)
			{
				return false;
			}
		}
		return double.Parse(newEntry.timeStr) < double.Parse(oldEntry.timeStr);
	}

	public static void Save()
	{
		int num = 0;
		Player player = null;
		if (GameController.coopOn)
		{
			PlayerRunData winnerData = RunData.GetWinnerData();
			if (winnerData == null)
			{
				num = 0;
			}
			else if (winnerData.playerID >= 0)
			{
				num = winnerData.playerID;
			}
		}
		RunHistoryEntry runHistoryEntry = new RunHistoryEntry();
		runHistoryEntry.loopCount = GameController.loopCount;
		runHistoryEntry.tierCount = GameController.tierCount;
		runHistoryEntry.stageCount = GameController.stageCount;
		runHistoryEntry.coop = GameController.coopOn;
		runHistoryEntry.timeText = Globals.TimeToString(GameController.totalTime);
		runHistoryEntry.timeStr = GameController.totalTime.ToString();
		runHistoryEntry.loopMode = GameController.loopCount > 0;
		runHistoryEntry.speedMode = Level.isBossRushMode;
		runHistoryEntry.hardMode = GameController.runModifier.HasMod(HardRunMod.staticID);
		runHistoryEntry.extraGold = !Level.isBossRushMode && JewelerNpc.goldTraded;
		runHistoryEntry.randomMode = GameController.runModifier.HasMod(RandRunMod.staticID);
		runHistoryEntry.floorLock = EpicBeardWizardNpc.levelLocked;
		runHistoryEntry.superSura = RunData.superSuraDefeated;
		player = GameController.activePlayers[num];
		for (int i = 0; i < runHistoryEntry.arcanaIDs.Length - 1; i++)
		{
			if (player.assignedSkills[i] != null)
			{
				runHistoryEntry.arcanaIDs[i] = player.assignedSkills[i].skillID;
				if (player.assignedSkills[i].isSignature)
				{
					runHistoryEntry.arcanaTypes[i] = 2;
				}
				else
				{
					runHistoryEntry.arcanaTypes[i] = (player.assignedSkills[i].IsEmpowered ? 1 : 0);
				}
			}
		}
		if (player.stockSkill != null)
		{
			runHistoryEntry.arcanaIDs[runHistoryEntry.arcanaIDs.Length - 1] = player.stockSkill.skillID;
			runHistoryEntry.arcanaTypes[runHistoryEntry.arcanaIDs.Length - 1] = (player.stockSkill.IsEmpowered ? 1 : 0);
		}
		string[] array = player.inventory.GetItemIDList().ToArray();
		for (int j = 0; j < array.Length; j++)
		{
			if (array[j] != null && !(array[j] == string.Empty))
			{
				runHistoryEntry.relicIDs[j] = array[j];
			}
		}
		runHistoryEntry.outfitID = player.equippedOutfit.outfitID;
		runHistoryEntry.outfitUpgraded = player.outfitEnhanced;
		if (Level.isBossRushMode)
		{
			runHistoryEntry.gameMode = GameMode.Speed;
		}
		else if (GameController.loopCount > 0)
		{
			runHistoryEntry.gameMode = GameMode.Endless;
		}
		else
		{
			runHistoryEntry.gameMode = GameMode.Standard;
		}
		if (IsBetterRun(runHistoryEntry, GameDataManager.gameVars.GetRunEntries()[(int)runHistoryEntry.gameMode]))
		{
			GameDataManager.gameVars.SetRunEntry(runHistoryEntry);
			RunHistoryUI.newRecordFlags[(int)runHistoryEntry.gameMode] = true;
		}
	}
}

using System;
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using UnityEngine;
using UnityEngine.UI;

public class UnlockNotifier : MonoBehaviour
{
	public enum NoticeType
	{
		Spell,
		Signature,
		Relic,
		Outfit
	}

	public class NoticeVars
	{
		public string noticeID;

		public string headerMsg;

		public string infoMsg;

		public Sprite iconSprite;

		public NoticeType noticeType;

		public NoticeVars(string givenID, string givenHeader, string givenInfo, Sprite givenSprite, NoticeType givenType)
		{
			noticeID = givenID;
			headerMsg = givenHeader;
			infoMsg = givenInfo;
			iconSprite = givenSprite;
			noticeType = givenType;
		}
	}

	private static UnlockNotifier instance;

	private Animator anim;

	private Queue<NoticeVars> noticeQueue;

	private GameObject unlockObj;

	private Image arcanaImage;

	private Image relicImage;

	private Image outfitImage;

	private Image outfitIconImage;

	private Image iconImage;

	private Text headerText;

	private Text infoText;

	public Sprite arcanaSprite;

	public Sprite arcanaSigSprite;

	private bool playAnimation;

	private bool animationComplete;

	private bool noticeIsActive;

	private ChaosQuickStopwatch displayStopwatch = new ChaosQuickStopwatch(1.5f);

	private bool displayTimeStarted;

	public static UnlockNotifier Instance => instance;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			UnityEngine.Object.Destroy(gameObject);
			return;
		}
		instance = this;
		UnityEngine.Object.DontDestroyOnLoad(gameObject);
		anim = GetComponent<Animator>();
		noticeQueue = new Queue<NoticeVars>(20);
		InitRefs();
		GameController.levelLoadEventHandlers = (GameController.LevelLoadEventHandler)Delegate.Combine(GameController.levelLoadEventHandlers, new GameController.LevelLoadEventHandler(OnLevelLoaded));
	}

	private void InitRefs()
	{
		unlockObj = transform.Find("UnlockObject").gameObject;
		arcanaImage = unlockObj.transform.Find("Arcana").GetComponent<Image>();
		relicImage = unlockObj.transform.Find("Relic").GetComponent<Image>();
		outfitImage = unlockObj.transform.Find("Outfit").GetComponent<Image>();
		outfitIconImage = unlockObj.transform.Find("OutfitIcon").GetComponent<Image>();
		outfitIconImage.material = new Material(outfitIconImage.material);
		iconImage = unlockObj.transform.Find("Icon").GetComponent<Image>();
		headerText = unlockObj.transform.Find("Header").GetComponent<Text>();
		infoText = unlockObj.transform.Find("Info").GetComponent<Text>();
		TextManager.AddUIRef(string.Empty, headerText);
		TextManager.AddUIRef(string.Empty, infoText);
	}

	private void LateUpdate()
	{
		if (!playAnimation)
		{
			return;
		}
		animationComplete = anim.AnimPlayed(0.75f);
		if (noticeIsActive)
		{
			if (!displayStopwatch.IsRunning && animationComplete)
			{
				if (displayTimeStarted)
				{
					noticeIsActive = false;
					anim.Play("Hide", -1, 0f);
				}
				else
				{
					displayStopwatch.IsRunning = true;
				}
				displayTimeStarted = !displayTimeStarted;
			}
		}
		else if (animationComplete)
		{
			if (noticeQueue.Count > 0)
			{
				noticeIsActive = true;
				SetNotice(noticeQueue.Dequeue());
				anim.Play("Show", -1, 0f);
				SoundManager.PlayAudio("UnlockNotifierOutro");
			}
			else
			{
				playAnimation = false;
			}
		}
	}

	public void Notify(string givenID, NoticeType givenType)
	{
		if (noticeQueue.Count == 0 && !playAnimation)
		{
			SoundManager.PlayAudio("UnlockNotifierIntro");
		}
		switch (givenType)
		{
		case NoticeType.Spell:
		case NoticeType.Signature:
			noticeQueue.Enqueue(new NoticeVars(givenID, TextManager.GetSkillName(givenID) + TextManager.GetUIText("unlockNotifier-unlockHeader"), TextManager.GetUIText("unlockNotifier-arcanaInfo"), IconManager.GetSkillIcon(givenID), givenType));
			break;
		case NoticeType.Relic:
			noticeQueue.Enqueue(new NoticeVars(givenID, TextManager.GetItemName(givenID) + TextManager.GetUIText("unlockNotifier-unlockHeader"), TextManager.GetUIText("unlockNotifier-relicInfo"), IconManager.GetItemIcon(givenID), NoticeType.Relic));
			break;
		case NoticeType.Outfit:
			noticeQueue.Enqueue(new NoticeVars(givenID, TextManager.GetOutfitName(givenID) + TextManager.GetUIText("unlockNotifier-unlockHeader"), TextManager.GetUIText("unlockNotifier-outfitInfo"), IconManager.GetItemIcon(givenID), NoticeType.Outfit));
			break;
		}
		playAnimation = true;
	}

	public void SetNotice(NoticeVars givenVars)
	{
		switch (givenVars.noticeType)
		{
		case NoticeType.Spell:
			arcanaImage.enabled = true;
			arcanaImage.sprite = arcanaSprite;
			relicImage.enabled = false;
			outfitIconImage.enabled = false;
			outfitImage.enabled = false;
			iconImage.enabled = true;
			iconImage.sprite = givenVars.iconSprite;
			break;
		case NoticeType.Signature:
			arcanaImage.enabled = true;
			arcanaImage.sprite = arcanaSigSprite;
			relicImage.enabled = false;
			outfitIconImage.enabled = false;
			outfitImage.enabled = false;
			iconImage.enabled = true;
			iconImage.sprite = givenVars.iconSprite;
			break;
		case NoticeType.Relic:
			arcanaImage.enabled = false;
			relicImage.enabled = true;
			outfitIconImage.enabled = false;
			outfitImage.enabled = false;
			iconImage.enabled = true;
			iconImage.sprite = givenVars.iconSprite;
			break;
		case NoticeType.Outfit:
			arcanaImage.enabled = false;
			relicImage.enabled = false;
			iconImage.enabled = false;
			outfitIconImage.enabled = true;
			outfitImage.enabled = true;
			outfitIconImage.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[givenVars.noticeID].outfitColorIndex);
			break;
		}
		headerText.text = givenVars.headerMsg;
		infoText.text = givenVars.infoMsg;
	}

	private void OnLevelLoaded(string next, string prev)
	{
		noticeQueue.Clear();
		noticeIsActive = false;
		playAnimation = false;
		animationComplete = true;
		anim.Play("Hide", -1, 1f);
	}
}
