	relicImages[entryIndex].sprite = IconManager.GetItemIcon(loadoutEntries[entryIndex].relicID);
	loadoutText[entryIndex].text = TextManager.GetOutfitName(loadoutEntries[entryIndex].outfitID);
	outfitImages[entryIndex].material.SetFloat("_PaletteIndex", Outfit.OutfitDict[loadoutEntries[entryIndex].outfitID].outfitColorIndex);
	for (int i = 0; i < arcanaBGs[entryIndex].Length; i++)
	{
		arcanaBGs[entryIndex][i].sprite = arcanaBGSprites[GetArcanaBGIndex(i, loadoutEntries[entryIndex].arcanaIDs[i])];
		arcanaImages[entryIndex][i].sprite = IconManager.GetSkillIcon(loadoutEntries[entryIndex].arcanaIDs[i]);
	}
}

private void UpdateCurrentLoadout(LoadoutEntry givenLoadout = null)
{
	if (givenLoadout == null)
	{
		if (curPlayer == null)
		{
			curLoadout.Reset();
			return;
		}
		curLoadout.outfitID = curPlayer.outfitID;
		curLoadout.relicID = curPlayer.designatedItemID;
		curLoadout.arcanaIDs[0] = curPlayer.GetBasicSkill().skillID;
		curLoadout.arcanaIDs[1] = curPlayer.GetDashSkill().skillID;
		curLoadout.arcanaIDs[2] = curPlayer.GetAnyStandardSkill().skillID;
		curLoadout.arcanaIDs[3] = curPlayer.GetSignatureSkill().skillID;
	}
	else
	{
		if (Outfit.OutfitIsInUse(givenLoadout.outfitID, curPlayer.playerID))
		{
			curLoadout.outfitID = curPlayer.outfitID;
		}
		else
		{
			curLoadout.outfitID = givenLoadout.outfitID;
		}
		curLoadout.relicID = givenLoadout.relicID;
		curLoadout.arcanaIDs[0] = givenLoadout.arcanaIDs[0];
		curLoadout.arcanaIDs[1] = givenLoadout.arcanaIDs[1];
		curLoadout.arcanaIDs[2] = givenLoadout.arcanaIDs[2];
		curLoadout.arcanaIDs[3] = givenLoadout.arcanaIDs[3];
	}
	RandomizeCamPose();
	curRelicImage.sprite = IconManager.GetItemIcon(curLoadout.relicID);
	curOutfitImage.material.SetFloat("_PaletteIndex", Outfit.OutfitDict[curLoadout.outfitID].outfitColorIndex);
	for (int i = 0; i < curArcanaImages.Length; i++)
	{
		curArcanaImages[i].sprite = IconManager.GetSkillIcon(curLoadout.arcanaIDs[i]);
		curArcanaBGs[i].sprite = arcanaBGSprites[GetArcanaBGIndex(i, curLoadout.arcanaIDs[i])];
	}
