private void HandleConfirm()
{
	if (!confirmVisible)
	{
		ToggleConfirmWindow();
	}
	else if (inputDev.GetButtonDown("Confirm"))
	{
		if (yesText.color == Globals.uiSelectedColor)
		{
			if (confirmingEquip)
			{
				EquipSelected();
			}
			else
			{
				SaveCurrent();
			}
		}
		ToggleConfirmWindow(show: false);
	}
	else if (inputDev.GetButtonUp("Cancel"))
	{
		ToggleConfirmWindow(show: false);
	}
	else
	{
		if (!inputDev.DirectionWasPressed(InputDirection.Down) && !inputDev.DirectionWasPressed(InputDirection.Up))
		{
			return;
		}
		SoundManager.PlayAudio("MenuMove");
		if ((!inputDev.DirectionWasPressed(InputDirection.Down) || !(yesText.color == Globals.uiSelectedColor)) && (!inputDev.DirectionWasPressed(InputDirection.Up) || !(noText.color == Globals.uiSelectedColor)))
		{
			if (yesText.color == Globals.uiSelectedColor)
			{
				yesText.color = Globals.uiNotSelectedColor;
				noText.color = Globals.uiSelectedColor;
			}
			else
			{
				yesText.color = Globals.uiSelectedColor;
				noText.color = Globals.uiNotSelectedColor;
			}
		}
	}
}

private void ToggleConfirmWindow(bool show = true)
{
	if (confirmingSave && (GameController.pvpOn || SceneManager.GetActiveScene().name.Contains("PvP")))
	{
		SoundManager.PlayAudio("MenuError");
		confirmingSave = false;
		return;
	}
	noText.color = Globals.uiSelectedColor;
	yesText.color = Globals.uiNotSelectedColor;
	if (confirmingEquip)
	{
		confirmText.text = TextManager.GetUIText("loadoutMenu-load");
	}
	else
	{
		confirmText.text = TextManager.GetUIText("loadoutMenu-save");
	}
	confirmRectTrans.anchoredPosition = new Vector3(confirmRectTrans.anchoredPosition.x, loadoutRectTrans[curNavIndex].anchoredPosition.y);
	if (show)
	{
		confirmObj.SetActive(value: true);
		confirmVisible = true;
		SoundManager.PlayAudio("Equip");
	}
	else
	{
		confirmVisible = false;
		confirmingEquip = false;
		confirmingSave = false;
		confirmObj.SetActive(value: false);
	}
}

private void EquipSelected()
{
	UpdateCurrentLoadout(loadoutEntries[curNavIndex]);
	SoundManager.PlayAudio("Equip");
	if (!(curPlayer == null))
	{
		curPlayer.EquipOutfit(curLoadout.outfitID);
		GameDataManager.Save(updateCurrentData: true, updatePlayerData: true);
		curPlayer.inventory.ClearInventory(keepHubOnly: false, keepCursed: true);
		if (!GameController.pvpOn && !SceneManager.GetActiveScene().name.Contains("PvP"))
		{
