public class ChaosMouseCursor : MonoBehaviour
{
	private static ChaosMouseCursor instance;

	public bool customCursorDisabled = true;

	private Image cursorImage;

	private Canvas canvas;

	private float idleCounter;

	private float idleHideThreshold = 10f;

	private bool hidden;

	private Vector3 lastInputPos;

	public static ChaosMouseCursor Instance => instance;

	public bool Hidden => hidden;

	private void Awake()
	{
		if (instance != null && instance != this)
		{
			Object.Destroy(gameObject);
			return;
		}
		instance = this;
		Object.DontDestroyOnLoad(gameObject);
		cursorImage = GetComponentInChildren<Image>();
		canvas = GetComponent<Canvas>();
		Toggle();
	}

	private void Update()
	{
		if (!LoadingScreen.loading)
		{
			HandleCursorIdleTime();
		}
		if (!customCursorDisabled)
		{
			cursorImage.transform.position = Input.mousePosition;
		}
	}

	private void HandleCursorIdleTime()
	{
		if (lastInputPos != Input.mousePosition || Input.GetMouseButtonDown(0) || Input.GetMouseButtonDown(1) || Input.GetMouseButtonDown(2))
		{
			if (hidden)
			{
				Show();
			}
			if (idleCounter != 0f)
			{
				idleCounter = 0f;
			}
		}
		else if (!hidden)
		{
			if (idleCounter >= idleHideThreshold)
			{
				Hide();
			}
			else
			{
				idleCounter += Time.deltaTime;
			}
		}
		lastInputPos = Input.mousePosition;
	}

	public void Hide()
	{
		Cursor.visible = false;
		cursorImage.enabled = false;
		hidden = true;
	}

	public void Show()
	{
		if (customCursorDisabled)
		{
			Toggle(enable: false);
		}
		else
		{
			Toggle();
		}
		hidden = false;
	}

	public void Toggle(bool enable = true)
	{
		Cursor.lockState = CursorLockMode.Confined;
		if (enable)
		{
			Cursor.visible = false;
			cursorImage.enabled = true;
			customCursorDisabled = false;
			canvas.enabled = true;
		}
		else
		{
			Cursor.visible = true;
			cursorImage.enabled = false;
			customCursorDisabled = true;
			canvas.enabled = false;
		}
	}

	private void OnApplicationFocus(bool hasFocus)
	{
		if (hasFocus)
		{
			StartCoroutine(OptionsMenu.SetCursorLock());
		}
	}
}
