			{
				SetPrimaryController(tempController);
			}
			else if ((tempController.type == ControllerType.Keyboard || tempController.type == ControllerType.Mouse) && inputScheme == InputScheme.Gamepad)
			{
				SetPrimaryController(tempController);
			}
