private void Update()
{
	if (!playersReady)
	{
		TogglePlayerInvulnerable(status: true);
		if (BothPlayersAlive && (BothPlayersReady || matchInProgress))
		{
			ResetPlayers(fullReset: true);
			playersReady = true;
			matchInProgress = true;
			if (applyAirRoomBuffs)
			{
				ApplyAirBuffs();
			}
			else if (applyEarthRoomBuffs)
			{
				ApplyEarthBuffs();
			}
			else if (applyFireRoomBuffs)
			{
				ApplyFireBuffs();
			}
			StartCoroutine(StartBattle());
		}
	}
	else if (!matchOver)
	{
		if (!BothPlayersAlive)
		{
			StartCoroutine(MatchOver());
			matchOver = true;
			return;
		}
		HandleSkillSpawn();
	}
	Player[] activePlayers = GameController.activePlayers;
	foreach (Player player in activePlayers)
	{
		if (player.fsm.currentStateName.Contains("Fall"))
		{
			if (!playerFallCheck[player.playerID])
			{
				player.lastCheckpoint = respawnLocations[Random.Range(0, respawnLocations.Count)];
				player.fall.preFallPos = player.lastCheckpoint;
				playerFallCheck[player.playerID] = true;
			}
		}
		else if (playerFallCheck[player.playerID])
		{
			playerFallCheck[player.playerID] = false;
		}
	}
}

private void HandleSkillSpawn()
{
	if (!resetSkillStopwatch.IsRunning)
	{
		resetSkillStopwatch.IsRunning = true;
		LootManager.ResetAvailableSkills();
	}
	if (ChaosStopwatch.Check(skillSpawnStopwatchID))
	{
		skillSpawnStopwatchID = ChaosStopwatch.Begin(skillSpawnTime + Random.Range(-1f, 1f));
		droppedSkillID = LootManager.GetSkillID();
		if (!(droppedSkillID == string.Empty))
		{
			skillSpawnLocIndex = (skillSpawnLocIndex + Random.Range(1, skillSpawnLocCount)) % skillSpawnLocCount;
			Vector3 vector = skillSpawnLocations[skillSpawnLocIndex];
			Vector3 spawnLocation = vector;
			int amount = 1;
			string skillID = droppedSkillID;
			bool droppedEmpowered = DroppedEmpowered;
			LootManager.DropSkill(spawnLocation, amount, skillID, 0f, 0f, null, useLifeTime: true, droppedEmpowered);
			vector.y -= 0.5f;
			Player.SpawnAllyPortal(vector, 0.5f);
		}
	}
}

