private void AddWinToken(int playerID, Color capeColor)
{
	playerID = Mathf.Clamp(playerID, 0, 1);
	GameObject gameObject = Object.Instantiate(winCountTokenPrefab);
	RectTransform component = gameObject.GetComponent<RectTransform>();
	gameObject.transform.SetParent(winCountTransform[playerID]);
	float num = 0.14f * (float)(playerWinCounts[playerID] - 1);
	num = ((playerID != 0) ? (1f - num - 0.14f) : num);
	component.anchorMin = new Vector2(num, 0f);
	component.anchorMax = new Vector2(num + 0.14f, 1f);
	component.offsetMin = Vector2.zero;
	component.offsetMax = Vector2.zero;
	gameObject.transform.Find("CapeColor").GetComponent<Image>().color = capeColor * 1.4f;
	capeColor *= 0.4f;
	capeColor.a = 1f;
	gameObject.transform.Find("Circle").GetComponent<Image>().color = capeColor;
	gameObject.GetComponent<Animator>().Play("Spawn");
}

private IEnumerator StartBattle()
{
	LootManager.Reset();
	GameUI.BroadcastNoticeMessage(" ");
	skillSpawnStopwatchID = ChaosStopwatch.Begin(skillSpawnTime);
	GameController.stageTitleUI.Announce(TextManager.GetUIText("pvp-ready"), 0f, 100, Color.white);
	yield return Globals.waitForOne;
	SoundManager.PlayBGM("Boss");
	if (pvpMode == PvPMode.Round)
	{
		GameController.stageTitleUI.Announce((roundCounter == maxRoundCount) ? TextManager.GetUIText("pvp-finalRound") : (TextManager.GetUIText("pvp-round") + " " + roundCounter), 0f, 100, Color.white);
		SoundManager.PlayAudio("Woosh");
		yield return Globals.waitForTwo;
	}
	GameController.stageTitleUI.AnnounceFight(TextManager.GetUIText("pvp-fight"));
	CameraController.ShakeCamera(0.75f);
	yield return Globals.waitForQuarter;
	SoundManager.PlayAudio("MetalBell");
	GameController.TogglePvpMode(pvpStatus: true);
	TogglePlayerInvulnerable(status: false);
}

private IEnumerator MatchOver()
{
	Player winner = null;
	if (GameController.activePlayers.Length == 0)
	{
		yield break;
	}
	if (!GameController.AllPlayersDead())
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!player.fsm.currentStateName.Contains("Dead"))
			{
				winner = player;
				playerWinCounts[player.playerID]++;
				break;
			}

		buttonPrompts = transform.Find("PvPUI/ButtonPrompts").gameObject;
		confirmImage = buttonPrompts.transform.Find("Confirm/Image").GetComponent<Image>();
		cancelImage = buttonPrompts.transform.Find("Cancel/Image").GetComponent<Image>();
		TextManager.AddUIRef("pvp-confirm", buttonPrompts.transform.Find("Confirm/Text").GetComponent<Text>());
		TextManager.AddUIRef("pvp-cancel", buttonPrompts.transform.Find("Cancel/Text").GetComponent<Text>());
		buttonPrompts.gameObject.SetActive(value: false);
		p1StartPos = transform.Find("PlayerSpawnLocations/P1Spawn").position;
		p2StartPos = transform.Find("PlayerSpawnLocations/P2Spawn").position;
	}

	private void Start()
	{
		SetStageLayout();
		GameController.coopOn = true;
		GameUI.SetMoneyStatus(givenStatus: false);
		matchOver = false;
		matchInProgress = false;
		playersReady = false;
		playerReadyCheck = new bool[numberOfPlayers];
		playerFallCheck = new bool[numberOfPlayers];
		playerWinCounts = new int[numberOfPlayers];
		for (int i = 0; i < numberOfPlayers; i++)
		{
			playerReadyCheck[i] = false;
			playerFallCheck[i] = false;
			playerWinCounts[i] = 0;
		}
		respawnLocations = new List<Vector3>();
		Transform transform = base.transform.Find("RespawnLocations");
		Transform[] componentsInChildren = transform.GetComponentsInChildren<Transform>();
		foreach (Transform transform2 in componentsInChildren)
		{
			if (transform2 != transform)
			{
				respawnLocations.Add(transform2.position);
			}
		}
		skillSpawnLocations = new List<Vector3>();
		Transform transform3 = base.transform.Find("SkillSpawnLocations");
		Transform[] componentsInChildren2 = transform3.GetComponentsInChildren<Transform>();
		foreach (Transform transform4 in componentsInChildren2)
		{
			if (transform4 != transform3)
			{
				skillSpawnLocations.Add(transform4.position);
			}
		}
		skillSpawnLocCount = skillSpawnLocations.Count;
		skillSpawnLocIndex = Random.Range(0, skillSpawnLocations.Count);
		LootManager.ResetAvailableSkills();
		pvpMode = PvPMode.Round;
		roundCounter = 1;
		base.transform.Find("PvPUI").GetComponent<Canvas>().worldCamera = Camera.main;
	}

	private void SetStageLayout()
	{
		if (availableRoomDict == null)
		{
			availableRoomDict = new Dictionary<string, GameObject>();
			GameObject gameObject = GameObject.Find("PvPRooms").gameObject;
			Room[] componentsInChildren = gameObject.GetComponentsInChildren<Room>();
			foreach (Room room in componentsInChildren)
			{
				availableRoomDict.Add(room.gameObject.name, room.gameObject);
			}
		}
		if (!availableRoomDict.ContainsKey(selectedRoomName))
		{
			selectedRoomName = "DefaultRoom";
		}
		forceEmpowerDrop = selectedRoomName.Contains("Lightning");
		applyAirRoomBuffs = selectedRoomName.Contains("Air");
		applyEarthRoomBuffs = selectedRoomName.Contains("Earth");
		applyFireRoomBuffs = selectedRoomName.Contains("Fire");
		lightStageEffects.Toggle(forceEmpowerDrop);
		airStageEffects.Toggle(applyAirRoomBuffs);
		foreach (KeyValuePair<string, GameObject> item in availableRoomDict)
		{
			if (item.Value != null)
			{
				if (item.Key == selectedRoomName)
				{
					selectedRoom = item.Value.GetComponent<Room>();
					item.Value.SetActive(value: true);
				}
			if (player != null)
			{
				player.health.hitStunModifierStat.Modify(earthStunMod, addMod: true);
			}
		}
	}

	private void ApplyFireBuffs()
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player != null)
			{
				player.health.damageTakenStat.Modify(fireDmgMod, addMod: true);
			}
		}
	}

	private void TogglePlayerInvulnerable(bool status)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.health.invulnerable = status;
		}
	}

	private void ResetPlayers(bool fullReset = false)
	{
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.myOrigin = ((player.playerID != 0) ? p2StartPos : p1StartPos);
			player.lastCheckpoint = player.myOrigin;
			player.ResetPlayer(originPosition: true, fullyRestoreHealth: true, resetState: true, fullReset);
			Player.SpawnAllyPortal(player.transform.position);
			List<GameObject> list = new List<GameObject>();
			player.CleanUpPlayerSummonsList();
			foreach (GameObject playerSummons in player.playerSummonsList)
			{
				if (playerSummons != null && playerSummons != player.gameObject)
				{
					list.Add(playerSummons);
				}
			}
			foreach (GameObject item in list)
			{
				Entity component = item.GetComponent<Entity>();
				if (component != null && component.fsm.HasState("Dead"))
				{
					component.fsm.ChangeState("Dead");
				}
				Ward component2 = item.GetComponent<Ward>();
				if (component2 != null)
				{
					component2.DestroyWard();
				}
			}
			list.Clear();
			player.CleanUpPlayerSummonsList();
		}
	}

	private void ResetStage(bool fullReset = false)
	{
		GameUI.BroadcastNoticeMessage(" ");
		if (fullReset)
		{
			for (int i = 0; i < numberOfPlayers; i++)
			{
				playerWinCounts[i] = 0;
			}
			Transform[] array = winCountTransform;
			foreach (Transform transform in array)
			{
				Transform[] componentsInChildren = transform.GetComponentsInChildren<Transform>();
				foreach (Transform transform2 in componentsInChildren)
				{
					if (transform2 != transform)
					{
						Object.Destroy(transform2.gameObject);
					}
				}
			}
			buttonPrompts.gameObject.SetActive(value: false);
			ChaosStopwatch.Stop(skillSpawnStopwatchID);
			LootManager.Reset();
		}
		GameController.itemSpawner.Reset();
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			Object.DestroyImmediate(player.gameObject);
		}
		GameController.p1Joined = false;
				}
			}
		}
		if (winner != null)
		{
			roundCounter++;
			GameController.stageTitleUI.AnnounceVictory(TextManager.GetUIText("pvp-victory"));
		}
		else
		{
			GameController.stageTitleUI.Announce(TextManager.GetUIText("pvp-double"), 2.5f, 100, null, null, showUnderline: true, 1f, 0.5f);
		}
		TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
		SoundManager.PlayAudio("Explosion2");
		SoundManager.PlayAudio("FloorVictory");
		yield return Globals.waitForHalf;
		GameController.TogglePvpMode(pvpStatus: false);
		yield return Globals.waitForOne;
		yield return Globals.waitForOne;
		SoundManager.PlayAudio("SwordDraw");
		if (winner != null)
		{
			AddWinToken(winner.playerID, winner.capeColor);
		}
		yield return Globals.waitForTwo;
		bool inputDetected = false;
		int selection = -1;
		if (pvpMode == PvPMode.Round)
		{
			int winnerExists = -1;
			for (int j = 0; j < numberOfPlayers; j++)
			{
				if (playerWinCounts[j] >= (int)((float)maxRoundCount * 0.5f + 1f))
				{
					winnerExists = j;
					break;
				}
			}
			if (winnerExists == -1)
			{
				ResetStage();
				yield break;
			}
			roundCounter = 1;
			if (winner != null)
			{
				GameController.stageTitleUI.Announce(TextManager.GetUIText((winnerExists != 0) ? "playerName-1" : "playerName-0") + " " + TextManager.GetUIText("pvp-winner"), 3f, 100, null, null, showUnderline: false);
				requestRestartConfirmation = true;
				yield return Globals.waitForTwo;
			}
		}
		if (requestRestartConfirmation)
		{
			requestRestartConfirmation = false;
			confirmImage.sprite = GameUI.GetInputSprite(winner.inputDevice.inputScheme);
			cancelImage.sprite = GameUI.GetInputSprite(winner.inputDevice.inputScheme, "Cancel");
			buttonPrompts.gameObject.SetActive(value: true);
			GameController.PauseAllPlayers();
			TogglePlayerInvulnerable(status: true);
			while (!inputDetected)
			{
				if (InputController.GetAnyDeviceButtonDown("Confirm") != null)
				{
					selection = 0;
					inputDetected = true;
				}
				else if (InputController.GetAnyDeviceButtonUp("Cancel") != null)
				{
					selection = 1;
					inputDetected = true;
				}
				yield return null;
			}
		}
		SoundManager.PlayBGM(string.Empty);
		matchInProgress = false;
		switch (selection)
		{
		case 0:
			ResetStage(fullReset: true);
			break;
		case 1:
			ResetStage(fullReset: true);
			GameController.LoadLevel("PvP");
			break;
		}
	}

	public virtual void OnTriggerStay2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact" && (playerCheck = col.transform.parent.gameObject.GetComponent<Player>()) != null)
		{
			playerReadyCheck[playerCheck.playerID] = true;
		}
	}

	public virtual void OnTriggerExit2D(Collider2D col)
	{
		if (col.gameObject.name == "AllyFloorContact" && (playerCheck = col.transform.parent.gameObject.GetComponent<Player>()) != null)
		{
			playerReadyCheck[playerCheck.playerID] = false;
		}
	}
