	private void OnControllerConnected(ControllerStatusChangedEventArgs args)
	{
		for (int i = 0; i < Players.Length; i++)
		{
			if (Players[i] == null)
			{
				continue;
			}
			if (chaosInputs[Players[i]].primaryController == args.controller)
			{
				AssignControllerToPlayer(Players[i], args.controller, removeFromOtherPlayers: true);
				return;
			}
			if (chaosInputs[Players[i]].controllerCount == 0 && ((i == 0 && GameController.p1Joined) || (i == 1 && GameController.p2Joined)))
			{
				tempController = GetFreeController();
				if (tempController != null)
				{
					AssignControllerToPlayer(Players[i], tempController, removeFromOtherPlayers: false);
					return;
				}
			}
			else if (i == 0 && GameController.p1Joined && !GameController.coopOn && !GameController.pvpOn)
			{
				AssignControllerToPlayer(Players[i], args.controller, removeFromOtherPlayers: true);
				return;
			}
		}
		AssignControllerToPlayer(SysPlayer, args.controller, removeFromOtherPlayers: true);
	}

	private void OnControllerDisconnected(ControllerStatusChangedEventArgs args)
	{
		for (int i = 0; i < Players.Length; i++)
		{
			if (Players[i] == null)
			{
				continue;
			}
			if (chaosInputs[Players[i]].primaryController != null && args.controller != null && chaosInputs[Players[i]].primaryController == args.controller && !GameUI.pauseMenu.paused)
			{
				GameController.pauseQueued = true;
			}
			Players[i].controllers.RemoveController(args.controllerType, args.controllerId);
			if (!ChaosInputDevice.lockControllerInput && chaosInputs[Players[i]].controllerCount <= 0 && chaosInputs != null && chaosInputs.ContainsKey(Players[i]) && chaosInputs[Players[i]].controllerCount == 0 && ((i == 0 && GameController.p1Joined) || (i == 1 && GameController.p2Joined)))
			{
				tempController = GetFreeController();
				if (tempController != null)
				{
					AssignControllerToPlayer(Players[i], tempController, removeFromOtherPlayers: false);
				}
			}
		}
	}

