public static void CreateElementMapForAll(string actionName, KeyCode keyCode, Pole pole)
{
	DeleteElementMapForAll(actionName, pole);
	tempActionID = ReInput.mapping.GetAction(actionName).id;
	if (MouseKeyCodes.Contains(keyCode))
	{
		foreach (Controller controller in ReInput.controllers.Controllers)
		{
			if (controller is Mouse)
			{
				tempCounter = 0;
				tempIndex = GetMouseButtonIndex(keyCode);
				foreach (ControllerElementIdentifier buttonElementIdentifier in controller.ButtonElementIdentifiers)
				{
					if (tempCounter == tempIndex)
					{
						break;
					}
				}
				if (tempIndex >= 0)
				{
					foreach (ControllerMap mouseMap in MouseMaps)
					{
						if (mouseMap.controllerId == controller.id)
						{
							tempActionMap = new ActionElementMap(tempActionID, controller.ButtonElementIdentifiers[tempIndex].elementType, controller.ButtonElementIdentifiers[tempIndex].id);
							mouseMap.RemoveElementAssignmentConflicts(tempActionMap);
							mouseMap.CreateElementMap(new ElementAssignment(ControllerType.Mouse, controller.ButtonElementIdentifiers[tempIndex].elementType, controller.ButtonElementIdentifiers[tempIndex].id, AxisRange.Full, keyCode, ModifierKeyFlags.None, tempActionID, pole, invert: false));
						}
					}
				}
			}
		}
		return;
	}
	foreach (ControllerMap keyboardMap in KeyboardMaps)
	{
		tempActionMap = new ActionElementMap(tempActionID, ControllerElementType.Button, pole, UnityToRewiredKeyCode(keyCode), ModifierKey.None, ModifierKey.None, ModifierKey.None);
		HandleConflicts(keyboardMap, tempActionMap);
		keyboardMap.CreateElementMap(ReInput.mapping.GetAction(actionName).id, pole, keyCode, ModifierKeyFlags.None);
	}
}

public static void HandleConflicts(ControllerMap cMap, ActionElementMap actionMap)
{
	tempConflicts.Clear();
	foreach (ElementAssignmentConflictInfo item in cMap.ElementAssignmentConflicts(actionMap))
	{
		if (item.actionId != ReInput.mapping.GetAction("Cancel").id && item.actionId != ReInput.mapping.GetAction("Confirm").id && item.actionId != ReInput.mapping.GetAction("Menu").id && (item.actionId != ReInput.mapping.GetAction("MoveHorizontal").id || (item.keyCode != KeyCode.LeftArrow && item.keyCode != KeyCode.RightArrow)) && (item.actionId != ReInput.mapping.GetAction("MoveVertical").id || (item.keyCode != KeyCode.UpArrow && item.keyCode != KeyCode.DownArrow)))
		{
			tempConflicts.Add(item);
		}
	}
	for (int i = 0; i < tempConflicts.Count; i++)
	{
		cMap.DeleteElementMap(tempConflicts[i].elementMapId);
	}
}

