	private static FileStream fileStream;

	private static string SavePathStr => BasePathStr + steamIDStr;
	public static bool GameCleared => gameData != null && gameData.gameStats != null && gameData.gameStats.GetEnemyDefeatedCount("FinalBoss") > 0;

	private static T LoadFromFile<T>(string targetFileName)
	{
		if (!Directory.Exists(SavePathStr))
		{
			Directory.CreateDirectory(SavePathStr);
		}
		T val = default;
		bool flag = false;
		if (File.Exists(SavePathStr + targetFileName))
		{
			targetFileName = SavePathStr + targetFileName;
		}
		else
		{
			if (!File.Exists(BasePathStr + targetFileName))
		{
			fileStream = File.Create(targetFileName);
			formatter.Serialize(fileStream, givenObj);
			fileStream.Close();
		}
	}

	public static void SaveSettings()
	{
		SaveToFile(gameSettings, settingFileStr);
	}

	public static void LoadSettings()
	{
		gameSettings = LoadFromFile<GameSettings>(settingFileStr);
		if (gameSettings == null)
		{
			gameSettings = new GameSettings();
		}
	}

	public static void ResetGameSettings()
	{
		if (gameSettings == null)
		{
			gameSettings = new GameSettings();
		}
		else
		{
			gameSettings.Reset();
		}
	}

	public static void Save(bool updateCurrentData = true, bool updatePlayerData = false)
	{
		if (gameData != null)
		{
			if (updateCurrentData)
			{
				gameData.UpdateData();
			}
			if (updatePlayerData)
			{
				gameData.SavePlayerData();
			}
			SaveToFile(gameData, dataFileStr);
		}
	}

	public static void LoadChaosData()
	{
		GameData givenData = LoadFromFile<GameData>(dataFileStr);
		if (CheckData(givenData) && CheckAgainstChaos(givenData))
		{
			gameData = givenData;
			SaveToFile(gameData, chaosFileStr);
			return;
		}
		givenData = LoadFromFile<GameData>(chaosFileStr);
		if (CheckData(givenData))
		{
			gameData = givenData;
			SaveToFile(gameData, dataFileStr);
		}
		else
		{
			gameData = new GameData();
			SaveToFile(gameData, dataFileStr);
			SaveToFile(gameData, chaosFileStr);
		}
	}

	public static void Load()
	{
		gameData = LoadFromFile<GameData>(dataFileStr);
		if (!CheckData(gameData))
		{
			gameData = new GameData();
		}
	}

	private static bool CheckData(GameData givenData)
	{
		return givenData?.IsValid() ?? false;
	}

	private static bool CheckAgainstChaos(GameData givenData)
	{
		if (givenData == null)
		{
			return false;
		}
		GameData gameData = LoadFromFile<GameData>(chaosFileStr);
		if (!CheckData(gameData))
		{
			return true;
		}
		return givenData.GetUnlockedSkillCount() >= gameData.GetUnlockedSkillCount() && givenData.GetUnlockedItemCount() >= gameData.GetUnlockedItemCount() && givenData.GetUnlockedOutfitCount() >= gameData.GetUnlockedOutfitCount();
	}

	public static void ResetAllData()
	{
		Debug.Log("GAME DATA CLEARED!");
		if (gameData != null)
		{
			gameData.ResetData();
		}
		ResetGameVars();
		SaveToFile(gameData, chaosFileStr);
		Save();
	}

	public static void SaveGameVars()
	{
		SaveToFile(gameVars, varsFileStr);
	}

	public static void LoadGameVars()
	{
		gameVars = LoadFromFile<GameVars>(varsFileStr);
		if (gameVars == null)
		{
			gameVars = new GameVars();
		}
	}

	public static void ResetGameVars()
	{
		if (gameVars == null)
		{
			gameVars = new GameVars();
		}
		else
		{
			gameVars.Reset();
		}
	}

	public static void LoadInitial(bool mainInit = false)
	{
		LoadSettings();
		if (mainInit)
		{
			LoadChaosData();
		}
		else
		{
			Load();
		}
		TextManager.SetLanguage(gameSettings.chaosLang);
		if (gameData != null)
		{
			gameData.UnlockStartingSkillsAndItems();
		}
		LoadGameVars();
	}
}

